partsCss:
/* Steel Tactical: dark steel tablet UI from the girls-und-panzer start screen and panel. */
[data-skin-part="sidebar-rail"], [data-skin-part="settings-nav"] {
  background: linear-gradient(160deg, #2f3a3d 0%, #1a2124 55%, #101517 100%) !important;
}
[data-skin-part="rail-icon"][data-skin-state="active"] {
  box-shadow: inset 0 -3px 0 #e0782a;
}
[data-skin-part="tab"] { letter-spacing: .1em; font-weight: 800 !important; }
[data-skin-part="tab"][data-skin-state="active"] { color: #ffffff !important; }
[data-skin-part="tab"][data-skin-state="active"]::after { height: 3px !important; border-radius: 0 !important; }
[data-skin-part="settings-page"] h1 { font-weight: 900; letter-spacing: .04em; }
[data-skin-part="settings-page"] h1::after {
  content: ""; display: block; width: 30px; height: 2px; margin-top: .55rem; background: #e0782a;
}
[data-skin-part="button"][data-skin-variant="primary"] {
  background: linear-gradient(180deg, #f0912f, #d0661c) !important;
  color: #140d06 !important; font-weight: 800; letter-spacing: .06em;
  box-shadow: 0 8px 20px rgb(224 120 42 / .25);
}
[data-skin-part="button"][data-skin-variant="default"]:hover, [data-skin-part="button"][data-skin-variant="outline"]:hover {
  border-color: #e0782a !important;
}
[data-skin-part="chip"] { letter-spacing: .12em; font-weight: 800; }
[data-skin-part="modal"] { border-top: 2px solid #e0782a !important; }
[data-skin-part="composer-field"] { box-shadow: inset 0 -3px 0 #3a4447; }
[data-skin-part="composer-field"]:focus-within { box-shadow: inset 0 -3px 0 #e0782a; }
[data-skin-part="message"][data-skin-role="user"] { background: linear-gradient(90deg, rgb(43 51 55 / .35), transparent 70%); }
